#!/usr/bin/env bash
# Phase P6, step 1: cut the PXUI repository out of Rays, with history.
#
#   tools/split-pxui.sh <rays-repo> <source-ref> <output-dir>
#
# Clones <rays-repo> (never touched), keeps the PXUI paths of <source-ref> with their history
# (git filter-repo) and adds ONE commit of generated files from tools/split-pxui/ (workspace
# manifest, cargo config, toolchain, license, AGENTS.md, README, gate policy, CI, Cargo.lock).
# Moved paths keep their repo-relative location, so every `../../fixtures/...` style path in the
# crates is valid both here and under Rays' `pxui/` checkout. Refuses to run if <output-dir> exists.
# Needs: git, git-filter-repo, cargo. Nothing is pushed or published.
set -euo pipefail

die() { echo "split-pxui: $*" >&2; exit 1; }
[ $# -eq 3 ] || die "usage: $0 <rays-repo> <source-ref> <output-dir>"
rays=$(cd "$1" && pwd) || die "no such repository: $1"
ref=$2
[ -e "$3" ] && die "output exists, refusing to overwrite: $3"
here=$(cd "$(dirname "$0")" && pwd)
tpl=$here/split-pxui
command -v git-filter-repo >/dev/null || die "git-filter-repo is missing (brew install git-filter-repo)"

sha=$(git -C "$rays" rev-parse --verify "$ref^{commit}") || die "unknown ref: $ref"
mkdir -p "$(dirname "$3")"
out=$(cd "$(dirname "$3")" && pwd)/$(basename "$3")
scratch=$(mktemp -d)
cleanup() { rc=$?; rm -rf "$scratch"; [ $rc -eq 0 ] || rm -rf "$out"; exit $rc; }
trap cleanup EXIT

CRATES="ogpu_core ogpu_mock ogpu_metal metal_sys ogpu_vulkan vulkan_sys native_layer_token_sys input sdl3 sdl3_sys mem_sys cfmt pxui pxui_text pxui_render pxui_sdl pxui_wayland pxui_atspi"
# Everything else the crates own, at the same repo-relative path.
EXTRA="tools/t tools/cc-stack.sh tools/gate/Cargo.toml tools/gate/src/main.rs tools/gate/shape-allowlist.tsv
 assets/fonts fixtures/pxui_render fixtures/shaders/ogpu_metal packaging/sdl3.lock
 specification/pxui.md specification/sdl3.md specification/metal.md specification/vulkan docs/pxui-baseline.md"

# Inputs taken from the source ref before history is rewritten.
show() { git -C "$rays" show "$sha:$1"; }
show LICENSE > "$scratch/LICENSE"
show rust-toolchain.toml > "$scratch/rust-toolchain.toml"
show Cargo.lock > "$scratch/Cargo.lock"
show docs/development.md | awk '/^## Vulkan on Linux/{p=1; sub(/^## /,"# ")} /^## /&&!/^## Vulkan on Linux/{p=0} p' > "$scratch/vulkan-linux.md"
[ -s "$scratch/vulkan-linux.md" ] || die "docs/development.md has no 'Vulkan on Linux' section"

git clone -q --no-local --no-checkout "$rays" "$out"
cd "$out"
git remote remove origin
git for-each-ref --format='%(refname)' | xargs -n1 git update-ref -d   # only the source commit survives
git update-ref refs/heads/main "$sha"
git symbolic-ref HEAD refs/heads/main

args=()
# Before 57487bbd7 the Rust tree lived under rs/: follow it, so history reaches back to the port's start.
# ponytail: crates renamed since (ogpu -> ogpu_core, cfmt_sys, metal) keep history only from their rename.
for c in $CRATES; do args+=(--path "crates/$c" --path "rs/crates/$c"); done
for p in $EXTRA; do args+=(--path "$p" --path "rs/$p"); done
git filter-repo --force "${args[@]}" --path-rename rs/:
git checkout -q main

# --- the one generated commit ---------------------------------------------------------------
cp "$tpl/Cargo.toml" Cargo.toml
mkdir -p .cargo .github/workflows docs
cp "$tpl/cargo-config.toml" .cargo/config.toml
cp "$tpl/ci.yml" .github/workflows/ci.yml
cp "$tpl/README.md" README.md
cp "$tpl/AGENTS.md" AGENTS.md
cp "$tpl/gate-policy.rs" tools/gate/src/policy.rs
cp "$scratch/LICENSE" LICENSE
cp "$scratch/rust-toolchain.toml" rust-toolchain.toml
cp "$scratch/vulkan-linux.md" docs/vulkan-linux.md
printf '/target\n' > .gitignore

# The gate engine is shared; its unit tests exercise Rays' policy, so they stay in Rays.
awk '/^#\[cfg\(test\)\]$/{exit} {print}' tools/gate/src/main.rs > "$scratch/main.rs" && mv "$scratch/main.rs" tools/gate/src/main.rs
# Keep only the shape exceptions of the crates that live here.
pat=$(echo "$CRATES" | tr ' ' '|')
awk -F'\t' -v pat="^crates/($pat)/" '/^#/ || $1 ~ pat' tools/gate/shape-allowlist.tsv > "$scratch/allow.tsv" && mv "$scratch/allow.tsv" tools/gate/shape-allowlist.tsv

# Rays' lockfile, pruned to this workspace by cargo: same cosmic-text versions as Rays resolves.
cp "$scratch/Cargo.lock" Cargo.lock
cargo metadata --format-version 1 --offline > /dev/null 2>&1 || cargo metadata --format-version 1 > /dev/null

git add -A
git commit -q -m "Standalone PXUI workspace: manifest, cargo config, toolchain, license, AGENTS.md, README, gate policy, CI, lockfile

Generated by tools/split-pxui.sh from Rays $sha."
echo "split-pxui: $out ready ($(git rev-list --count HEAD) commits, source $sha)"
